/** CC hook matcher semantics (see file header). */
export function ccMatcherMatches(matcher: string | undefined, tool: string): boolean {
  if (matcher === undefined || matcher === '' || matcher === '*') return true;
  if (/^[\w|-]+$/.test(matcher)) return matcher.split('|').includes(tool);
  try {
    return new RegExp(matcher).test(tool);
  } catch {
    return false;
  }
}

interface Merged {
  contexts: string[];
  messages: string[];
  blockReasons: string[];
  stop?: HookResult;
  updatedToolOutput?: unknown;
  updatedMCPToolOutput?: unknown;
}

function absorb(m: Merged, r: HookResult | undefined, wasSync: boolean): void {
  if (!r) return;
  const hso: HookSpecificOutput | undefined = r.hookSpecificOutput;
  if (hso?.additionalContext) m.contexts.push(hso.additionalContext);
  if (r.systemMessage) m.messages.push(r.systemMessage);
  if (!wasSync) return;
  if (r.continue === false && !m.stop) m.stop = r;
  if (r.decision === 'block') m.blockReasons.push(r.reason ?? r.stopReason ?? 'blocked');
  if (hso?.updatedToolOutput !== undefined && m.updatedToolOutput === undefined) m.updatedToolOutput = hso.updatedToolOutput;
  if (hso?.updatedMCPToolOutput !== undefined && m.updatedMCPToolOutput === undefined) {
    m.updatedMCPToolOutput = hso.updatedMCPToolOutput;
  }
}

function build(m: Merged): HookResult {
  const hso: HookSpecificOutput = { hookEventName: 'PostToolUse' };
  let hasHso = false;
  if (m.contexts.length) {
    hso.additionalContext = m.contexts.join('\n\n---\n\n');
    hasHso = true;
  }
  if (m.updatedToolOutput !== undefined) {
    hso.updatedToolOutput = m.updatedToolOutput;
    hasHso = true;
  }
  if (m.updatedMCPToolOutput !== undefined) {
    hso.updatedMCPToolOutput = m.updatedMCPToolOutput;
    hasHso = true;
  }
  const result: HookResult = m.stop
    ? { ...m.stop }
    : { continue: true, suppressOutput: !hasHso && m.messages.length === 0 && m.blockReasons.length === 0 };
  if (hasHso) result.hookSpecificOutput = hso;
  if (m.messages.length) result.systemMessage = m.messages.join('\n');
  if (m.blockReasons.length) {
    result.decision = 'block';
    result.reason = m.blockReasons.join('\n');
  }
  return result;
}

/**
 * Run every handler the matching groups name, each id once, in file order.
 * `handlers` and `groups` are injectable for tests.
 */
export async function posttoolDispatch(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
  handlers: Record<string, Fn> = POSTTOOL_HANDLERS,
  groups: PosttoolGroup[] = POSTTOOL_GROUPS,
): Promise<HookResult> {
  const tool = input.tool_name ?? '';
  const merged: Merged = { contexts: [], messages: [], blockReasons: [] };
  const seen = new Set<string>();
  for (const group of groups) {
    if (!ccMatcherMatches(group.matcher, tool)) continue;
    for (const { id, async } of group.hooks) {
      if (seen.has(id)) continue;
      seen.add(id);
      const fn = handlers[id];
      if (!fn) {
        ctx.log(HOOK_NAME, `no handler for ${id} (skipped)`);
        continue;
      }
      try {
        absorb(merged, await fn(input, ctx), !async);
      } catch (err) {
        ctx.log(HOOK_NAME, `${id} failed (isolated): ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  }
  return build(merged);
}

/** Entry-map handler (registered as posttool/tool-dispatcher). */
export function posttoolToolDispatcher(input: HookInput, ctx: HookContext = NOOP_CTX): Promise<HookResult> {
  return posttoolDispatch(input, ctx);
}
